            elif c == 'U':
                row.append(('U', None))
            elif c == 'D':
                row.append((None, 'D'))
        grid.append(row)
    return grid

def config_to_str(grid):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0
    res = []
    for i in range(n):
        row = []
        for j in range(m):
            if grid[i][j][0] is not None:
                row.append(grid[i][j][0])
            else:
                row.append(grid[i][j][1])
        res.append(''.join(row))
    return res

def apply_operation(grid, i, j):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0
    new_grid = [row[:] for row in grid]
    # The 2x2 square is at (i,j), (i,j+1), (i+1,j), (i+1,j+1)
    # We need to rotate the four half-tiles in this square
    # The rotation is 90 degrees clockwise
    # The four half-tiles are:
    # top-left: (i,j), top-right: (i,j+1), bottom-left: (i+1,j), bottom-right: (i+1,j+1)
    # The rotation changes their positions and orientations

    # Extract the four half-tiles
    tl = new_grid[i][j]
    tr = new_grid[i][j+1]
    bl = new_grid[i+1][j]
    br = new_grid[i+1][j+1]

    # Determine the new positions and orientations after rotation
    # The rotation is 90 degrees clockwise, so:
    # The top-left becomes bottom-left, top-right becomes top-left, bottom-right becomes top-right, bottom-left becomes bottom-right
    # But the orientations must also be rotated accordingly

    # The new top-left is the old bottom-left rotated
    # The new top-right is the old top-left rotated
    # The new bottom-left is the old bottom-right rotated
    # The new bottom-right is the old top-right rotated

    # Helper function to rotate a half-tile
    def rotate_half_tile(half):
        if half[0] == 'L':
            return ('U', None)
        elif half[0] == 'U':
            return ('R', None)
        elif half[0] == 'R':
            return ('D', None)
        elif half[0] == 'D':
            return ('L', None)
        elif half[1] == 'L':
            return (None, 'D')
        elif half[1] == 'U':
            return (None, 'L')
        elif half[1] == 'R':
            return (None, 'U')
        elif half[1] == 'D':
            return (None, 'R')
        else:
            return (None, None)

    # Rotate each half-tile and place them in the new positions
    new_tl = rotate_half_tile(bl)
    new_tr = rotate_half_tile(tl)
    new_bl = rotate_half_tile(br)
    new_br = rotate_half_tile(tr)

    # Place the new half-tiles
    new_grid[i][j] = new_tl
    new_grid[i][j+1] = new_tr
    new_grid[i+1][j] = new_bl
    new_grid[i+1][j+1] = new_br

    return new_grid

def is_solvable(current, desired):
    # Check if the current and desired configurations have the same number of each type of half-tile
    # Since each operation preserves the count of each half-tile type, this is a necessary condition
    count_current = {'L': 0, 'R': 0, 'U': 0, 'D': 0}
    count_desired = {'L': 0, 'R': 0, 'U': 0, 'D': 0}

    for row in current:
        for cell in row:
            if cell[0] is not None:
                count_current[cell[0]] += 1
            else:
                count_current[cell[1]] += 1

    for row in desired:
        for cell in row:
            if cell[0] is not None:
                count_desired[cell[0]] += 1
            else:
                count_desired[cell[1]] += 1

    return count_current == count_desired

def bfs(current, desired, n, m):
    # Convert current and desired to a hashable form
    def config_to_tuple(grid):
        return tuple(tuple(tuple(cell) for cell in row) for row in grid)

    start = config_to_tuple(current)
    target = config_to_tuple(desired)

    if start == target:
        return []

    visited = set()
    queue = deque()
    queue.append((start, []))
    visited.add(start)

    while queue:
        current_config, path = queue.popleft()

        # Generate all possible operations
        for i in range(n - 1):
            for j in range(m - 1):
                # Apply the operation
                new_grid = [list(row) for row in current_config]
                new_grid = apply_operation(new_grid, i, j)
                new_config = config_to_tuple(new_grid)

                if new_config == target:
                    return path + [(i+1, j+1)]  # Convert to 1-based

                if new_config not in visited:
                    visited.add(new_config)
                    queue.append((new_config, path + [(i+1, j+1)]))

    return None

def solve():
    n, m, current_lines, desired_lines = read_input()
    current = parse_config(current_lines)
    desired = parse_config(desired_lines)

    if not is_solvable(current, desired):
        print(-1)
